"""Editable native SVG assets for WEIGHT TODAY. Components expose motion IDs."""
def illustration(kind,c):
    paper,yellow,green,brown,ink=[c[k] for k in ['paper','yellow','green','brown','ink']]
    defs=f'''<defs><linearGradient id="metal-{kind}" x2="1" y2="1"><stop stop-color="{paper}"/><stop offset=".5" stop-color="#C6CAB9"/><stop offset="1" stop-color="#849C86"/></linearGradient><linearGradient id="fabric-{kind}" x2=".7" y2="1"><stop stop-color="{brown}"/><stop offset="1" stop-color="#694832"/></linearGradient><linearGradient id="gold-{kind}" x2="1" y2="1"><stop stop-color="#F7D96F"/><stop offset="1" stop-color="#B68B2E"/></linearGradient></defs>'''
    def weight(id,x,y,s=1):
        return f'''<g transform="translate({x} {y}) scale({s})"><g id="{id}"><path d="M-34 0 Q-34-48 0-48 Q34-48 34 0" fill="none" stroke="{paper}" stroke-width="13"/><path d="M-63 0 H63 L92 118 Q95 138 70 138 H-70 Q-95 138-92 118Z" fill="url(#metal-{kind})"/><path d="M-61 15 H60" stroke="white" opacity=".45" stroke-width="4"/><path d="M-66 115 H67" stroke="{green}" opacity=".22" stroke-width="5"/><ellipse cy="62" rx="24" ry="20" fill="{green}" opacity=".2"/></g></g>'''
    def bench(id,x,y,s=1):
        return f'''<g transform="translate({x} {y}) scale({s})"><g id="{id}"><path d="M-125 30 V115 M125 30 V115" stroke="{paper}" stroke-width="16"/><path d="M-155-78 H155 M-155-35 H155 M-175 20 H175" stroke="url(#fabric-{kind})" stroke-width="30"/><path d="M-125-85 V20 M125-85 V20" stroke="{yellow}" stroke-width="9"/><path d="M-175 8 H175" stroke="{yellow}" stroke-width="4"/></g></g>'''
    if kind=='hook':
        content=f'''<ellipse cx="420" cy="535" rx="260" ry="23" fill="{ink}" opacity=".3"/><g id="hook-cable"><path d="M80 35 H760 M420 35 V140" fill="none" stroke="{paper}" stroke-width="7"/><circle cx="420" cy="150" r="15" fill="none" stroke="{yellow}" stroke-width="8"/></g>{weight('hook-weight',420,195,1.65)}<path id="hook-pressure" d="M240 490 Q420 535 600 490" fill="none" stroke="{yellow}" stroke-width="7"/>'''
    elif kind=='load':
        content=f'''<ellipse cx="420" cy="565" rx="330" ry="24" fill="{ink}" opacity=".3"/><path d="M420 175 V510 M285 535 H555" stroke="url(#metal-{kind})" stroke-width="28"/><path d="M350 510 H490 L530 550 H310Z" fill="{paper}"/><g id="scale-beam"><path d="M135 180 H705" stroke="{yellow}" stroke-width="17"/><circle cx="420" cy="180" r="30" fill="{paper}"/><circle cx="420" cy="180" r="11" fill="{brown}"/><g id="scale-left"><path d="M155 180 L65 410 M155 180 L255 410" stroke="{paper}" stroke-width="5"/><path d="M45 410 Q155 520 275 410Z" fill="url(#gold-{kind})"/></g><g id="scale-right"><path d="M685 180 L580 410 M685 180 L785 410" stroke="{paper}" stroke-width="5"/><path d="M565 410 Q685 520 800 410Z" fill="url(#gold-{kind})"/>{weight('scale-weight-a',653,305,.58)}{weight('scale-weight-b',729,323,.48)}</g></g><g id="scale-weight-c">{weight('scale-weight-core',156,308,.7)}</g>'''
    elif kind=='honest':
        content=f'''<g id="rope-anchor"><circle cx="120" cy="90" r="28" fill="{paper}"/><circle cx="720" cy="90" r="28" fill="{paper}"/></g><path id="rope" d="M120 90 Q420 175 720 90" fill="none" stroke="{yellow}" stroke-width="15" stroke-linecap="round"/><path d="M115 85 Q420 165 725 85" fill="none" stroke="{paper}" stroke-width="2" stroke-dasharray="6 11" opacity=".6"/>{weight('rope-weight',420,190,1.2)}'''
    elif kind=='release':
        content=f'''<ellipse cx="420" cy="590" rx="235" ry="25" fill="{ink}" opacity=".35"/><g id="bag-body"><path d="M260 225 Q180 250 190 495 M580 225 Q660 250 650 495" fill="none" stroke="{yellow}" stroke-width="28"/><path d="M350 185 V135 Q420 75 490 135 V185" fill="none" stroke="{paper}" stroke-width="20"/><path d="M260 200 Q420 120 580 200 L610 535 Q420 610 230 535Z" fill="url(#fabric-{kind})"/><path d="M280 240 Q420 165 560 240 L580 520 Q420 570 255 520Z" fill="none" stroke="{paper}" stroke-width="3" stroke-dasharray="7 8" opacity=".55"/><rect x="295" y="385" width="250" height="130" rx="24" fill="{yellow}"/><path d="M315 420 H525" stroke="{ink}" stroke-width="6"/><path d="M500 420 V445" stroke="{paper}" stroke-width="8"/></g><g id="bag-lid"><path d="M255 205 Q420 145 585 205 L565 310 Q420 365 275 310Z" fill="{brown}" stroke="{paper}" stroke-width="3"/><rect x="400" y="270" width="40" height="65" rx="7" fill="{yellow}"/></g>{weight('bag-weight-a',320,200,.7)}{weight('bag-weight-b',510,220,.6)}'''
    elif kind=='pause':
        content=bench('pause-bench',420,420,1.2)+f'''<g id="pause-clock"><circle cx="625" cy="135" r="88" fill="{paper}"/><circle cx="625" cy="135" r="73" fill="none" stroke="{brown}" stroke-width="3"/><path id="clock-hand" d="M625 75 V135 L665 165" fill="none" stroke="{green}" stroke-width="9" stroke-linecap="round"/><circle cx="625" cy="135" r="8" fill="{yellow}"/></g><g id="pause-leaf"><path d="M200 385 Q100 225 210 100" fill="none" stroke="{yellow}" stroke-width="8"/><path d="M160 230 Q65 150 90 110 Q180 115 160 230 M180 165 Q260 65 295 100 Q290 180 180 165" fill="{paper}"/></g><ellipse cx="420" cy="590" rx="290" ry="18" fill="{ink}" opacity=".35"/>'''
    elif kind=='tired':
        content=f'''<ellipse cx="420" cy="590" rx="200" ry="20" fill="{ink}" opacity=".3"/><g id="plant-pot"><path d="M305 415 H535 L505 575 H335Z" fill="url(#fabric-{kind})"/><rect x="290" y="405" width="260" height="35" rx="8" fill="{yellow}"/><path d="M355 455 V540 M420 455 V550 M485 455 V540" stroke="{paper}" opacity=".25" stroke-width="4"/></g><g id="plant-stem"><path d="M420 410 Q390 260 430 90" fill="none" stroke="{yellow}" stroke-width="11"/><path d="M415 330 Q270 330 265 225 Q395 210 415 330 M415 240 Q560 245 585 135 Q470 130 415 240 M426 155 Q315 155 330 50 Q420 55 426 155" fill="{paper}"/><path d="M300 255 L410 327 M550 165 L425 240 M350 75 L425 153" stroke="{green}" stroke-width="3" opacity=".5"/></g><g id="plant-wind" fill="none" stroke="{paper}" stroke-width="5" opacity=".7"><path d="M65 175 H210 Q255 175 240 145 M35 235 H185 M70 290 H230"/></g>'''
    elif kind=='rest':
        content=f'''<path id="rest-route" d="M80 535 C260 535 210 350 360 350 S545 185 760 185" fill="none" stroke="{paper}" stroke-width="12" stroke-dasharray="16 18"/>'''+bench('rest-bench',390,260,.8)+f'''<g id="rest-walker"><ellipse cx="95" cy="503" rx="19" ry="34" transform="rotate(28 95 503)" fill="{yellow}"/><ellipse cx="140" cy="535" rx="19" ry="34" transform="rotate(28 140 535)" fill="{yellow}"/></g><circle cx="765" cy="185" r="12" fill="{yellow}"/>'''
    elif kind=='today':
        content=f'''<ellipse cx="420" cy="590" rx="270" ry="20" fill="{ink}" opacity=".3"/><g id="calendar-back"><path d="M210 110 H655 L680 530 H185Z" fill="{brown}"/><rect x="195" y="135" width="470" height="410" rx="10" fill="{paper}"/><rect x="195" y="135" width="470" height="82" fill="{yellow}"/><text x="430" y="195" font-size="35" text-anchor="middle" fill="{ink}">TODAY</text><g fill="{green}" opacity=".13">'''+''.join(f'<rect x="{240+j*80}" y="{260+i*72}" width="42" height="38" rx="4"/>' for i in range(3) for j in range(5))+f'''</g><circle id="calendar-focus" cx="420" cy="350" r="49" fill="none" stroke="{brown}" stroke-width="8"/></g><g id="calendar-page"><path d="M200 145 H660 V530 L590 565 H200Z" fill="{paper}"/><path d="M590 530 H660 L590 565Z" fill="#D6CDB5"/><text x="430" y="260" font-size="52" text-anchor="middle" fill="{green}">TOMORROW</text><path d="M275 335 H580 M275 390 H530 M275 445 H470" stroke="{brown}" stroke-width="10" opacity=".4"/></g><g fill="{ink}"><rect x="270" y="100" width="18" height="70" rx="8"/><rect x="570" y="100" width="18" height="70" rx="8"/></g>'''
    else:
        content=f'''<g id="step-stones">'''+''.join(f'<ellipse cx="{155+j*230}" cy="{485-j*135}" rx="105" ry="39" fill="{paper}" opacity="{1-j*.2}"/><path d="M{50+j*230} {485-j*135} v20 q105 70 210 0 v-20" fill="{brown}"/>' for j in range(3))+f'''</g><g id="step-mark"><ellipse cx="135" cy="460" rx="17" ry="30" transform="rotate(25 135 460)" fill="{yellow}"/><ellipse cx="180" cy="475" rx="17" ry="30" transform="rotate(25 180 475)" fill="{yellow}"/></g>'''
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 840 640" aria-hidden="true">'+defs+content+'</svg>'
